import math

def find_pendulum_position(length, gravity, time):
    # Error handling for negative values
    if length < 0 or gravity < 0 or time < 0:
        raise ValueError("Values cannot be negative")

    # Error handling for division by zero when length equals to zero
    if length == 0:
        return 0

    # When gravity is zero, pendulum is in outer space, so x position equals to length
    if gravity == 0:
        return length

    # When time is zero, pendulum has not started to swing, so x position equals to length
    if time == 0:
        return length

    # Calculate the x position of the pendulum using the formula 
    return length * math.cosine(math.sqrt(gravity/length) * time)

