        if tensor.shape != tensors[0].shape:
            raise ValueError("All tensors should have the same number of dimensions")

    # Create a dictionary that stores game order as key and corresponding tensor as value
    game_dict = {order: tensor for order, tensor in zip(game_order, tensors)}

    # Arrange the game_order in ascending order
    ordered_game_order = sorted(game_order)

    # Arrange tensors according to the arranged game order
    ordered_tensors = [game_dict[order] for order in ordered_game_order]

